<script setup lang="ts">
import { computed, ref } from 'vue'
type Page='dashboard'|'bikes'|'plans'|'overhaul'|'maintenance'|'events'|'history'|'messages'|'mypage'
type Status='予定'|'案内待ち'|'案内済み'|'予約済み'|'完了'
type Plan={id:number;name:string;overhaulCount:number;maintenanceCount:number;inspectionCount:number}
type Bike={id:number;customer:string;name:string;maker:string;model:string;year:number;serial:string;planId:number;contractStart:string;contractEnd:string;overhaulUsed:number;maintenanceUsed:number;inspectionUsed:number;overhaulCompleted:string}
type Work={id:number;bikeId:number;date:string;status:Status;title:string;detail:string}
type EventCheck={id:number;bikeId:number;name:string;eventDate:string;inspectionDate:string;status:Status;memo:string}
type History={id:number;bikeId:number;date:string;category:string;title:string;detail:string}
const page=ref<Page>('dashboard'),role=ref<'staff'|'customer'>('staff'),selectedBikeId=ref(1),notice=ref(''),showMail=ref(false),mailTarget=ref('山田 太郎'),mailKind=ref('メンテナンスのご案内')
const today='2026年11月10日（火）'
const customers=[{name:'山田 太郎',email:'t.yamada@example.com'},{name:'佐藤 花子',email:'h.sato@example.com'},{name:'鈴木 一郎',email:'i.suzuki@example.com'}]
const plans=ref<Plan[]>([
{id:1,name:'プレミアムプラン',overhaulCount:1,maintenanceCount:4,inspectionCount:3},
{id:2,name:'スタンダードプラン',overhaulCount:1,maintenanceCount:3,inspectionCount:2},
{id:3,name:'ライトプラン',overhaulCount:1,maintenanceCount:2,inspectionCount:1},
])
const bikes=ref<Bike[]>([
{id:1,customer:'山田 太郎',name:'ロードバイク A',maker:'SPECIALIZED',model:'Tarmac SL8 Expert',year:2025,serial:'WSBC0250A001',planId:1,contractStart:'2026/12/01',contractEnd:'2027/11/30',overhaulUsed:0,maintenanceUsed:1,inspectionUsed:1,overhaulCompleted:''},
{id:2,customer:'佐藤 花子',name:'ロードバイク B',maker:'TREK',model:'Madone SL 7',year:2024,serial:'WTU12345678',planId:2,contractStart:'2026/12/01',contractEnd:'2027/11/30',overhaulUsed:0,maintenanceUsed:0,inspectionUsed:0,overhaulCompleted:''},
{id:3,customer:'鈴木 一郎',name:'ロードバイク C',maker:'GIANT',model:'TCR Advanced Pro',year:2023,serial:'GNT2023-0088',planId:3,contractStart:'2026/12/01',contractEnd:'2027/11/30',overhaulUsed:1,maintenanceUsed:2,inspectionUsed:0,overhaulCompleted:'2027/01/15'},
])
const planFor=(b:Bike)=>plans.value.find(p=>p.id===b.planId)??plans.value[0]
const overhauls=ref<Work[]>([
{id:1,bikeId:1,date:'2027/01/15',status:'予定',title:'年間オーバーホール',detail:'全体オーバーホール・消耗品点検'},
{id:2,bikeId:2,date:'2027/02/05',status:'予約済み',title:'年間オーバーホール',detail:'納車後初回オーバーホール'},
{id:3,bikeId:3,date:'2027/01/15',status:'完了',title:'年間オーバーホール',detail:'駆動系洗浄・ワイヤー交換'},
])
const maintenance=ref<Work[]>([
{id:1,bikeId:1,date:'2027/04/10',status:'完了',title:'春の目標イベント前メンテナンス',detail:'駆動系・変速・ブレーキ調整'},
{id:2,bikeId:1,date:'2027/06/05',status:'予定',title:'夏季メインイベントに向けたメンテナンス',detail:'消耗品・ホイール・ポジション確認'},
{id:3,bikeId:3,date:'2027/05/20',status:'完了',title:'シーズン前メンテナンス',detail:'変速・ブレーキ・タイヤ点検'},
{id:4,bikeId:3,date:'2027/08/01',status:'完了',title:'夏季イベント前メンテナンス',detail:'チェーン清掃・注油・各部増し締め'},
])
const eventChecks=ref<EventCheck[]>([
{id:1,bikeId:1,name:'シーズン開幕ロードレース',eventDate:'2027/04/18',inspectionDate:'2027/04/14',status:'予定',memo:'イベント直前の安全確認'},
{id:2,bikeId:1,name:'夏のメインイベント',eventDate:'2027/07/25',inspectionDate:'2027/07/21',status:'予定',memo:'タイヤ・ブレーキ・締結確認'},
{id:3,bikeId:2,name:'冬季サイクルイベント',eventDate:'2027/12/10',inspectionDate:'2027/12/07',status:'予定',memo:'次年度契約のイベント予定例'},
])
const histories=ref<History[]>([
{id:1,bikeId:1,date:'2027/04/10',category:'メンテナンス',title:'春の目標イベント前メンテナンス',detail:'駆動系・変速・ブレーキ調整'},
{id:2,bikeId:3,date:'2027/01/15',category:'オーバーホール',title:'年間オーバーホール',detail:'駆動系洗浄・ワイヤー交換'},
{id:3,bikeId:3,date:'2027/05/20',category:'メンテナンス',title:'シーズン前メンテナンス',detail:'変速・ブレーキ・タイヤ点検'},
{id:4,bikeId:3,date:'2027/08/01',category:'メンテナンス',title:'夏季イベント前メンテナンス',detail:'チェーン清掃・注油・各部増し締め'},
])
const newWorkBike=ref(1),newWorkDate=ref('2027-07-01'),newWorkTitle=ref('メインイベントに向けたメンテナンス'),newWorkDetail=ref('イベントに向けた状態確認・調整')
const newEventBike=ref(1),newEventName=ref(''),newEventDate=ref('2027-08-01'),newInspectionDate=ref('2027-07-28')
const selectedBike=computed(()=>bikes.value.find(b=>b.id===selectedBikeId.value)??bikes.value[0])
const remaining=(b:Bike,kind:'maintenance'|'inspection'|'overhaul')=>{const p=planFor(b);const used=kind==='maintenance'?b.maintenanceUsed:kind==='inspection'?b.inspectionUsed:b.overhaulUsed;const limit=kind==='maintenance'?p.maintenanceCount:kind==='inspection'?p.inspectionCount:p.overhaulCount;return Math.max(0,limit-used)}
const completedCount=computed(()=>histories.value.length),upcomingCount=computed(()=>overhauls.value.filter(x=>x.status!=='完了').length+maintenance.value.filter(x=>x.status!=='完了').length+eventChecks.value.filter(x=>x.status!=='完了').length),pendingCount=computed(()=>maintenance.value.filter(x=>x.status==='案内待ち').length+eventChecks.value.filter(x=>x.status==='案内待ち').length)
const allUpcoming=computed(()=>[
...overhauls.value.filter(x=>x.status!=='完了').map(x=>({...x,kind:'オーバーホール'})),
...maintenance.value.filter(x=>x.status!=='完了').map(x=>({...x,kind:'メンテナンス'})),
...eventChecks.value.filter(x=>x.status!=='完了').map(x=>({...x,date:x.inspectionDate,title:x.name,kind:'イベント前点検'})),
].sort((a,b)=>a.date.localeCompare(b.date)))
const customerBikes=computed(()=>bikes.value.filter(b=>b.customer==='山田 太郎'))
function setPage(p:Page){page.value=p;notice.value=''}
function addHistory(b:Bike,date:string,category:string,title:string,detail:string){histories.value.unshift({id:Math.max(0,...histories.value.map(h=>h.id))+1,bikeId:b.id,date,category,title,detail})}
function completeOverhaul(w:Work){if(w.status==='完了')return;const b=bikes.value.find(x=>x.id===w.bikeId);if(!b)return;if(remaining(b,'overhaul')<=0){notice.value='オーバーホールの契約回数を使い切っています。';return}w.status='完了';b.overhaulUsed++;b.overhaulCompleted=w.date;addHistory(b,w.date,'オーバーホール',w.title,w.detail);notice.value='オーバーホールを完了しました。メンテナンス予定はイベント・目標に合わせてスタッフが登録してください。'}
function completeMaintenance(w:Work){if(w.status==='完了')return;const b=bikes.value.find(x=>x.id===w.bikeId);if(!b)return;if(remaining(b,'maintenance')<=0){notice.value='メンテナンスの契約回数が残っていません。';return}w.status='完了';b.maintenanceUsed++;addHistory(b,w.date,'メンテナンス',w.title,w.detail);notice.value='メンテナンスを完了し、メンテナンス回数を1回消費しました。'}
function completeEvent(e:EventCheck){if(e.status==='完了')return;const b=bikes.value.find(x=>x.id===e.bikeId);if(!b)return;if(remaining(b,'inspection')<=0){notice.value='点検サポートの契約回数が残っていません。';return}e.status='完了';b.inspectionUsed++;addHistory(b,e.inspectionDate,'点検サポート',e.name,e.memo);notice.value='点検サポートを完了し、点検回数を1回消費しました。'}
function addMaintenance(){const b=bikes.value.find(x=>x.id===newWorkBike.value);if(!b)return;if(remaining(b,'maintenance')<=0){notice.value='この契約のメンテナンス残回数がありません。';return}maintenance.value.push({id:Math.max(0,...maintenance.value.map(x=>x.id))+1,bikeId:b.id,date:newWorkDate.value.replace(/-/g, '/'),status:'予定',title:newWorkTitle.value,detail:newWorkDetail.value});notice.value='メンテナンス計画を追加しました。実施完了までは回数を消費しません。'}
function addEvent(){const b=bikes.value.find(x=>x.id===newEventBike.value);if(!b||!newEventName.value.trim())return;if(remaining(b,'inspection')<=0){notice.value='この契約の点検サポート残回数がありません。';return}eventChecks.value.push({id:Math.max(0,...eventChecks.value.map(x=>x.id))+1,bikeId:b.id,name:newEventName.value,eventDate:newEventDate.value.replace(/-/g, '/'),inspectionDate:newInspectionDate.value.replace(/-/g, '/'),status:'予定',memo:'目標イベントに向けた点検サポート'});newEventName.value='';notice.value='目標イベントと点検予定を登録しました。'}
function sendMail(){showMail.value=false;notice.value=`${mailTarget.value} 様への「${mailKind.value}」を送信した想定のデモです（実際には送信されません）。`}
</script>
<template>
<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">R</div><div><strong>ROAD BIKE CARE</strong><small>メンテナンス管理</small></div></div><div class="side-label">店舗管理メニュー</div>
<button v-for="item in [{id:'dashboard',label:'ダッシュボード',icon:'▦'},{id:'bikes',label:'顧客・自転車管理',icon:'🚴'},{id:'plans',label:'プラン設定',icon:'▣'},{id:'overhaul',label:'オーバーホール',icon:'⚙'},{id:'maintenance',label:'メンテナンス計画',icon:'◷'},{id:'events',label:'目標イベント・点検',icon:'◇'},{id:'history',label:'メンテナンス履歴',icon:'▤'},{id:'messages',label:'連絡・メール管理',icon:'✉'}]" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="setPage(item.id as Page)"><span class="nav-icon">{{item.icon}}</span>{{item.label}}</button>
<div class="sidebar-bottom"><div class="side-label">表示モード</div><button class="mode-switch" @click="role=role==='staff'?'customer':'staff';page=role==='customer'?'mypage':'dashboard'"><span>{{role==='staff'?'店舗スタッフ':'顧客マイページ'}}</span><span>切替 ↗</span></button><div class="user"><div class="avatar">店</div><div><b>{{role==='staff'?'店舗管理者':'山田 太郎'}}</b><small>{{role==='staff'?'スタッフアカウント':'顧客アカウント'}}</small></div></div></div></aside>
<main class="main"><header class="topbar"><div class="breadcrumb">ROAD BIKE CARE <span>/</span> {{({dashboard:'ダッシュボード',bikes:'顧客・自転車管理',plans:'プラン設定',overhaul:'オーバーホール',maintenance:'メンテナンス計画',events:'目標イベント・点検',history:'メンテナンス履歴',messages:'連絡・メール管理',mypage:'マイページ'} as Record<Page,string>)[page]}}</div><div class="top-actions"><span class="today">{{today}}</span><div class="avatar">店</div></div></header><div class="content"><div v-if="notice" class="notice"><span>{{notice}}</span><button @click="notice=''">×</button></div>
<template v-if="page==='dashboard'"><div class="page-heading"><div><p class="eyebrow">ROAD BIKE SERVICE OVERVIEW</p><h1>ダッシュボード</h1><p class="sub">年間契約・オーバーホール・目標イベントに向けた作業計画を管理します。</p></div><button class="primary" @click="setPage('maintenance')">メンテナンス計画を作成</button></div>
<div class="callout"><b>年間契約サイクル：12月1日〜翌年11月30日</b><p>12月〜3月はオーバーホール期間、4月〜11月は目標イベントに合わせたメンテナンス・点検サポート期間を基本とします。</p></div>
<div class="stats"><div class="stat-card"><div class="stat-top"><span>登録自転車数</span><span class="stat-icon blue">🚴</span></div><strong>{{bikes.length}}</strong><small>台</small></div><div class="stat-card"><div class="stat-top"><span>未完了の作業予定</span><span class="stat-icon purple">⚙</span></div><strong>{{upcomingCount}}</strong><small>件</small></div><div class="stat-card"><div class="stat-top"><span>案内待ち</span><span class="stat-icon orange">✉</span></div><strong>{{pendingCount}}</strong><small>件</small></div><div class="stat-card"><div class="stat-top"><span>作業履歴</span><span class="stat-icon green">✓</span></div><strong>{{completedCount}}</strong><small>件</small></div></div>
<section class="panel"><div class="panel-head"><div><h2>直近の作業予定</h2><p>オーバーホール・メンテナンス・イベント前点検</p></div></div><div class="table-wrap"><table><thead><tr><th>予定日</th><th>作業区分</th><th>内容</th><th>顧客・自転車</th><th>状態</th></tr></thead><tbody><tr v-for="w in allUpcoming.slice(0,7)" :key="w.id+'-'+w.kind"><td><b>{{w.date}}</b></td><td>{{w.kind}}</td><td>{{w.title}}</td><td>{{bikes.find(b=>b.id===w.bikeId)?.customer}}<small class="cell-sub">{{bikes.find(b=>b.id===w.bikeId)?.model}}</small></td><td><span class="status info">{{w.status}}</span></td></tr></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>契約回数の状況</h2><p>オーバーホール・メンテナンス・点検サポートを独立して管理</p></div><button class="text-btn" @click="setPage('bikes')">契約一覧 →</button></div><div class="table-wrap"><table><thead><tr><th>顧客・自転車</th><th>プラン</th><th>オーバーホール</th><th>メンテナンス</th><th>点検サポート</th><th>契約期間</th></tr></thead><tbody><tr v-for="b in bikes" :key="b.id"><td><b>{{b.customer}}</b><small class="cell-sub">{{b.maker}} {{b.model}}</small></td><td>{{planFor(b).name}}</td><td>{{remaining(b,'overhaul')}} / {{planFor(b).overhaulCount}}回</td><td>{{remaining(b,'maintenance')}} / {{planFor(b).maintenanceCount}}回</td><td>{{remaining(b,'inspection')}} / {{planFor(b).inspectionCount}}回</td><td>{{b.contractStart}}〜{{b.contractEnd}}</td></tr></tbody></table></div></section></template>

<template v-else-if="page==='plans'"><div class="page-heading"><div><p class="eyebrow">PLAN MASTER</p><h1>プラン設定</h1><p class="sub">プランごとにオーバーホール・メンテナンス・点検サポートの回数を別々に設定します。</p></div></div><div class="callout"><b>回数枠はそれぞれ独立</b><p>メンテナンスを実施しても点検サポートの回数は減りません。契約終了時の残回数は失効し、翌年度への繰越はありません。</p></div><div class="section-grid"><section v-for="p in plans" :key="p.id" class="panel"><div class="panel-head"><div><h2>{{p.name}}</h2><p>年間契約プラン</p></div><span class="status success">有効</span></div><div class="detail-grid"><div><label>オーバーホール</label><b class="large">{{p.overhaulCount}}回</b></div><div><label>メンテナンス</label><b class="large">{{p.maintenanceCount}}回</b></div><div><label>点検サポート</label><b class="large">{{p.inspectionCount}}回</b></div></div></section></div><div class="panel-foot">※ 表示中のプラン回数はモック用の仮設定です。実際のプラン内容に合わせて変更する想定です。</div></template>

<template v-else-if="page==='bikes'"><div class="page-heading"><div><p class="eyebrow">CUSTOMERS & BICYCLES</p><h1>顧客・自転車・契約管理</h1><p class="sub">自転車ごとに年間プランと契約期間、各サービスの残回数を管理します。</p></div></div><section class="panel"><div class="panel-head"><div><h2>年間契約一覧</h2><p>{{bikes.length}}台の自転車が登録されています</p></div><span class="count">契約期間：12月1日〜翌年11月30日</span></div><div class="table-wrap"><table><thead><tr><th>顧客・自転車</th><th>契約プラン</th><th>契約期間</th><th>OH残</th><th>メンテ残</th><th>点検残</th><th></th></tr></thead><tbody><tr v-for="b in bikes" :key="b.id"><td><b>{{b.customer}}</b><small class="cell-sub">{{b.maker}} {{b.model}}</small></td><td>{{planFor(b).name}}</td><td>{{b.contractStart}}〜{{b.contractEnd}}</td><td>{{remaining(b,'overhaul')}}/{{planFor(b).overhaulCount}}</td><td>{{remaining(b,'maintenance')}}/{{planFor(b).maintenanceCount}}</td><td>{{remaining(b,'inspection')}}/{{planFor(b).inspectionCount}}</td><td><button class="outline small" @click="selectedBikeId=b.id">詳細</button></td></tr></tbody></table></div></section><section class="panel detail-panel"><div class="panel-head"><div><h2>契約詳細</h2><p>選択した自転車の契約回数</p></div><select v-model.number="selectedBikeId"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select></div><div class="detail-grid"><div><label>顧客</label><b>{{selectedBike.customer}}</b></div><div><label>自転車</label><b>{{selectedBike.maker}} {{selectedBike.model}}</b></div><div><label>プラン</label><b>{{planFor(selectedBike).name}}</b></div><div><label>契約期間</label><b>{{selectedBike.contractStart}}〜{{selectedBike.contractEnd}}</b></div><div><label>オーバーホール残</label><b class="remaining large">{{remaining(selectedBike,'overhaul')}}回</b></div><div><label>メンテナンス残</label><b class="remaining large">{{remaining(selectedBike,'maintenance')}}回</b></div><div><label>点検サポート残</label><b class="remaining large">{{remaining(selectedBike,'inspection')}}回</b></div><div><label>OH完了日</label><b>{{selectedBike.overhaulCompleted||'未実施'}}</b></div></div></section></template>

<template v-else-if="page==='overhaul'"><div class="page-heading"><div><p class="eyebrow">OVERHAUL MANAGEMENT</p><h1>オーバーホール</h1><p class="sub">年間プランに含まれるオーバーホールの予定・実績を管理します。</p></div></div><div class="callout"><b>基本実施期間：12月1日〜翌年3月31日</b><p>オーバーホールとメンテナンスは同じ年間プランに含まれます。完了日は記録しますが、その日から一定間隔でメンテナンス予定を自動生成することはありません。</p></div><section class="panel"><div class="panel-head"><div><h2>オーバーホール予定・実績</h2><p>実施完了時にオーバーホール回数を消費</p></div><span class="count">{{overhauls.length}}件</span></div><div class="table-wrap"><table><thead><tr><th>顧客</th><th>自転車</th><th>プラン</th><th>実施予定日</th><th>状態</th><th>契約残</th><th>操作</th></tr></thead><tbody><tr v-for="w in overhauls" :key="w.id"><td>{{bikes.find(b=>b.id===w.bikeId)?.customer}}</td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td>{{planFor(bikes.find(b=>b.id===w.bikeId)!).name}}</td><td>{{w.date}}</td><td><span class="status info">{{w.status}}</span></td><td>{{remaining(bikes.find(b=>b.id===w.bikeId)!,'overhaul')}}回</td><td><button v-if="w.status!=='完了'" class="outline small" @click="completeOverhaul(w)">実施完了</button><span v-else class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='maintenance'"><div class="page-heading"><div><p class="eyebrow">MAINTENANCE PLANNING</p><h1>メンテナンス計画</h1><p class="sub">顧客の目標イベントに合わせてスタッフが実施計画を作成します。</p></div></div><div class="callout"><b>固定周期ではなく、目標イベントに合わせた計画</b><p>2か月おきの自動生成は行いません。メインイベントの日程・目標・車体の状態を踏まえて必要なタイミングで計画します。実施完了時のみメンテナンス回数を消費します。</p></div><section class="panel"><div class="panel-head"><div><h2>メンテナンス計画を追加</h2><p>契約のメンテナンス残回数の範囲内で登録</p></div></div><div class="detail-grid"><div><label>顧客・自転車</label><select v-model.number="newWorkBike"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.model}}</option></select></div><div><label>予定日</label><input v-model="newWorkDate" type="date"/></div><div><label>計画名</label><input v-model="newWorkTitle"/></div><div><label>作業内容</label><input v-model="newWorkDetail"/></div></div><div class="modal-actions"><span class="muted">選択中の残回数：{{remaining(bikes.find(b=>b.id===newWorkBike)!,'maintenance')}}回</span><button class="primary" @click="addMaintenance">＋ 計画を登録</button></div></section><section class="panel"><div class="panel-head"><div><h2>メンテナンス計画一覧</h2><p>予定・案内・予約は回数を消費しません</p></div><span class="count">{{maintenance.length}}件</span></div><div class="table-wrap"><table><thead><tr><th>予定日</th><th>顧客・自転車</th><th>計画・作業内容</th><th>状態</th><th>残回数</th><th>操作</th></tr></thead><tbody><tr v-for="w in maintenance" :key="w.id"><td><b>{{w.date}}</b></td><td>{{bikes.find(b=>b.id===w.bikeId)?.customer}}<small class="cell-sub">{{bikes.find(b=>b.id===w.bikeId)?.model}}</small></td><td><b>{{w.title}}</b><small class="cell-sub">{{w.detail}}</small></td><td><select class="status-select" v-model="w.status"><option>予定</option><option>案内待ち</option><option>案内済み</option><option>予約済み</option></select></td><td>{{remaining(bikes.find(b=>b.id===w.bikeId)!,'maintenance')}}回</td><td><button v-if="w.status!=='完了'" class="outline small" @click="completeMaintenance(w)">実施完了</button><span v-else class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='events'"><div class="page-heading"><div><p class="eyebrow">TARGET EVENTS & INSPECTIONS</p><h1>目標イベント・点検サポート</h1><p class="sub">顧客のメインイベントと、その前に行う点検サポートを管理します。</p></div></div><div class="callout"><b>点検サポートはメンテナンスとは別枠</b><p>点検サポートの実施完了時にのみ、プランの点検回数を1回消費します。メンテナンス回数とは相互に影響しません。</p></div><section class="panel"><div class="panel-head"><div><h2>目標イベント・点検予定を追加</h2><p>顧客の目標イベントに合わせて点検日を設定</p></div></div><div class="detail-grid"><div><label>顧客・自転車</label><select v-model.number="newEventBike"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.model}}</option></select></div><div><label>イベント名</label><input v-model="newEventName" placeholder="例：年間メインイベント"/></div><div><label>イベント開催日</label><input v-model="newEventDate" type="date"/></div><div><label>点検予定日</label><input v-model="newInspectionDate" type="date"/></div></div><div class="modal-actions"><span class="muted">選択中の点検残回数：{{remaining(bikes.find(b=>b.id===newEventBike)!,'inspection')}}回</span><button class="primary" @click="addEvent">＋ イベントを登録</button></div></section><section class="panel"><div class="panel-head"><div><h2>イベント・点検サポート一覧</h2><p>点検完了時に点検サポート枠を消費</p></div></div><div class="table-wrap"><table><thead><tr><th>イベント名</th><th>顧客・自転車</th><th>開催日</th><th>点検日</th><th>状態</th><th>残回数</th><th>操作</th></tr></thead><tbody><tr v-for="e in eventChecks" :key="e.id"><td><b>{{e.name}}</b><small class="cell-sub">{{e.memo}}</small></td><td>{{bikes.find(b=>b.id===e.bikeId)?.customer}}<small class="cell-sub">{{bikes.find(b=>b.id===e.bikeId)?.model}}</small></td><td>{{e.eventDate}}</td><td>{{e.inspectionDate}}</td><td><span class="status info">{{e.status}}</span></td><td>{{remaining(bikes.find(b=>b.id===e.bikeId)!,'inspection')}}回</td><td><button v-if="e.status!=='完了'" class="outline small" @click="completeEvent(e)">点検完了</button><span v-else class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='history'"><div class="page-heading"><div><p class="eyebrow">SERVICE HISTORY</p><h1>メンテナンス履歴</h1><p class="sub">自転車ごとのオーバーホール・メンテナンス・点検サポートの履歴です。</p></div><select class="search" v-model.number="selectedBikeId"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select></div><section class="panel"><div class="panel-head"><div><h2>{{selectedBike.maker}} {{selectedBike.model}}</h2><p>{{selectedBike.customer}} 様の作業履歴</p></div><span class="count">{{histories.filter(h=>h.bikeId===selectedBikeId).length}}件</span></div><div class="table-wrap"><table><thead><tr><th>実施日</th><th>作業区分</th><th>作業内容</th><th>詳細</th></tr></thead><tbody><tr v-for="h in histories.filter(x=>x.bikeId===selectedBikeId).sort((a,b)=>b.date.localeCompare(a.date))" :key="h.id"><td><b>{{h.date}}</b></td><td>{{h.category}}</td><td>{{h.title}}</td><td>{{h.detail}}</td></tr></tbody></table></div></section></template>

<template v-else-if="page==='messages'"><div class="page-heading"><div><p class="eyebrow">COMMUNICATION</p><h1>連絡・メール管理</h1><p class="sub">イベント・メンテナンス予定に関する顧客連絡を管理します。</p></div><button class="primary" @click="showMail=true">✉ メールを作成</button></div><section class="panel"><div class="panel-head"><div><h2>案内待ちのメンテナンス・点検</h2><p>顧客への連絡が必要な予定</p></div><span class="status warning">{{pendingCount}}件</span></div><div class="table-wrap"><table><thead><tr><th>顧客</th><th>自転車</th><th>予定日</th><th>区分</th><th></th></tr></thead><tbody><tr v-for="w in [...maintenance.filter(x=>x.status==='案内待ち').map(x=>({...x,kind:'メンテナンス'})),...eventChecks.filter(x=>x.status==='案内待ち').map(x=>({...x,date:x.inspectionDate,title:x.name,kind:'点検サポート'}))]" :key="w.id"><td>{{bikes.find(b=>b.id===w.bikeId)?.customer}}</td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td>{{w.date}}</td><td>{{w.kind}}</td><td><button class="outline small" @click="mailTarget=bikes.find(b=>b.id===w.bikeId)?.customer||'';mailKind=w.kind+'のご案内';showMail=true">内容確認</button></td></tr></tbody></table></div></section></template>

<template v-else><div class="page-heading"><div><p class="eyebrow">CUSTOMER PORTAL</p><h1>マイページ</h1><p class="sub">ご登録のロードバイクと年間プランをご確認いただけます。</p></div><span class="customer-welcome">山田 太郎 様</span></div><section class="panel"><div class="panel-head"><div><h2>ご契約中のロードバイク</h2><p>{{customerBikes.length}}台</p></div><span class="status success">契約中</span></div><div v-for="b in customerBikes" :key="b.id" class="customer-bike"><div class="bike-symbol">🚴</div><div class="equipment-details"><b>{{b.maker}} {{b.model}}</b><small>{{planFor(b).name}} · 契約期間 {{b.contractStart}}〜{{b.contractEnd}}</small><small>オーバーホール残 {{remaining(b,'overhaul')}}回</small><small>メンテナンス残 {{remaining(b,'maintenance')}} / {{planFor(b).maintenanceCount}}回</small><small>点検サポート残 {{remaining(b,'inspection')}} / {{planFor(b).inspectionCount}}回</small></div></div></section><section class="panel"><div class="panel-head"><div><h2>メンテナンス・点検予定</h2><p>目標イベントに合わせたサポート予定</p></div></div><div class="table-wrap"><table><thead><tr><th>予定日</th><th>区分</th><th>内容</th><th>状態</th></tr></thead><tbody><tr v-for="w in [...maintenance.filter(x=>customerBikes.some(b=>b.id===x.bikeId)),...eventChecks.filter(x=>customerBikes.some(b=>b.id===x.bikeId)).map(x=>({...x,date:x.inspectionDate,title:x.name,kind:'点検サポート'}))].sort((a,b)=>a.date.localeCompare(b.date))" :key="w.id"><td>{{w.date}}</td><td>{{'kind' in w?w.kind:'メンテナンス'}}</td><td>{{w.title}}</td><td>{{w.status}}</td></tr></tbody></table></div></section></template>
</div></main></div>
<div v-if="showMail" class="modal-backdrop" @click.self="showMail=false"><div class="modal"><div class="modal-head"><div><p class="eyebrow">EMAIL PREVIEW</p><h2>メンテナンス案内メール</h2></div><button class="close" @click="showMail=false">×</button></div><label>送信先</label><select v-model="mailTarget"><option v-for="c in customers" :key="c.name">{{c.name}}</option></select><label>件名</label><input v-model="mailKind"/><label>本文</label><div class="mail-body">{{mailTarget}} 様<br><br>いつもご利用いただきありがとうございます。<br>メンテナンス・点検予定についてご案内いたします。<br><br>ご希望の日程がございましたら店舗までご連絡ください。<br><br>今後ともよろしくお願いいたします。</div><div class="modal-note">※ モックのため、実際のメール送信は行われません。</div><div class="modal-actions"><button class="outline" @click="showMail=false">閉じる</button><button class="primary" @click="sendMail">送信（デモ）</button></div></div></div>
</template>
